281: fn is_realtime_call_id_segment(segment: &str) -> bool {
282:     if segment.starts_with("rtc_") && segment.len() > "rtc_".len() {
283:         return true;
284:     }
285: 
286:     if segment.len() != 36 {
287:         return false;
288:     }
289: 
290:     segment.char_indices().all(|(index, ch)| match index {
291:         8 | 13 | 18 | 23 => ch == '-',
292:         _ => ch.is_ascii_hexdigit(),
293:     })
294: }
